mapper.select:
SELECT DISTINCT d.*
FROM doctor d
INNER JOIN schedule s ON s.doctor_id = d.id
WHERE d.department_id = #{deptId}
  AND s.work_date = #{workDate}
  AND s.registered_count < s.max_patients

SELECT d.id, u.username, u.real_name AS realName, u.phone, u.status, u.created_at AS createdAt, d.department_id AS departmentId, dept.name AS departmentName, d.title, d.specialty, d.introduction, d.registration_fee AS registrationFee, d.is_available AS isAvailable FROM doctor d INNER JOIN `user` u ON d.id = u.id LEFT JOIN department dept ON d.department_id = dept.id WHERE u.role = 'DOCTOR'
AND (LOWER(u.real_name) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR LOWER(u.username) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR u.phone LIKE CONCAT('%', #{keyword}, '%'))
AND d.department_id = #{departmentId}
AND u.status = #{status}
ORDER BY u.created_at DESC
